fn fnv1a64(bytes: &[u8]) -> u64 { let mut hash = 0xcbf29ce484222325u64; for &b in bytes { hash ^= b as u64; hash = hash.wrapping_mul(0x100000001b3); } hash } 
fn machine_code() -> String { let guid = std::process::Command::new("reg") .args(["query", r"HKLM\SOFTWARE\Microsoft\Cryptography", "/v", "MachineGuid"]) .creation_flags(CREATE_NO_WINDOW_LOCAL) .output() .ok() .and_then(|out| { if !out.status.success() { return None; } let text = String::from_utf8_lossy(&out.stdout); text.lines() .find(|line| line.to_ascii_lowercase().contains("machineguid")) .and_then(|line| line.split_whitespace().last()) .map(str::to_string) }) .unwrap_or_else(|| { let host = std::env::var("COMPUTERNAME").unwrap_or_default(); let drive = std::env::var("SystemDrive").unwrap_or_default(); format!("{host}|{drive}") }); let salted = format!("HikaDagger|{guid}"); format!("HIKA-{:016X}", fnv1a64(salted.as_bytes())) } 
fn validate_license_online(key: &str) -> Result<LicenseApiReply, String> { let payload = serde_json::json!({ "key": key.trim(), "machine_code": machine_code(), }).to_string(); let agent = LICENSE_HTTP.get_or_init(|| ureq::AgentBuilder::new() .timeout_connect(Duration::from_secs(12)) .timeout_read(Duration::from_secs(70)) .timeout_write(Duration::from_secs(12)) .build()); let response = agent.post(LICENSE_API_URL) .set("Content-Type", "application/json") .set("Cache-Control", "no-cache") .send_string(&payload) .map_err(|e| format!("License server unavailable: {e}"))?; let text = response .into_string() .map_err(|e| format!("Invalid license server response: {e}"))?; serde_json::from_str::<LicenseApiReply>(&text) .map_err(|e| format!("Invalid license server data: {e}")) } 
fn apply_valid_license(key: &str, reply: &LicenseApiReply) -> bool { if !reply.valid || (!reply.lifetime && reply.remaining_seconds == 0) { return false; } let Some(runtime) = LICENSE.get() else { return false; }; let now = Instant::now(); *runtime.key.lock().unwrap() = Some(key.trim().to_string()); *runtime.deadline.lock().unwrap() = if reply.lifetime { None } else { now.checked_add(Duration::from_secs(reply.remaining_seconds)) }; *runtime.last_ok.lock().unwrap() = Some(now); runtime.valid.store(true, Ordering::Release); if let Some(shared) = SHARED.get() { let desired = shared.desired_active.load(Ordering::Acquire); shared.active.store(desired, Ordering::Release); unsafe { SetEvent(shared.wake_event as HANDLE); } } true } 
fn invalidate_runtime_license() { if let Some(runtime) = LICENSE.get() { runtime.valid.store(false, Ordering::Release); *runtime.deadline.lock().unwrap() = None; } if let Some(shared) = SHARED.get() { shared.desired_active.store(false, Ordering::Release); shared.active.store(false, Ordering::Release); } } 
fn license_monitor(runtime: Arc<LicenseRuntime>) { unsafe { SetThreadPriority(GetCurrentThread(), THREAD_PRIORITY_BELOW_NORMAL); } let mut last_online_attempt = Instant::now(); loop { if runtime.stop.load(Ordering::Acquire) { break; } thread::sleep(Duration::from_secs(1)); if runtime.stop.load(Ordering::Acquire) { break; } if !runtime.valid.load(Ordering::Acquire) { continue; } let now = Instant::now(); let expired = runtime.deadline.lock().unwrap().map(|d| now >= d).unwrap_or(false); if expired { runtime.valid.store(false, Ordering::Release); clear_cached_license(); set_active(false); unsafe { if !HWND_MAIN.is_null() { PostMessageW(HWND_MAIN, WM_LICENSE_INVALID, 0, 0); } } continue; } if now.duration_since(last_online_attempt) < Duration::from_secs(LICENSE_CHECK_INTERVAL_SECS) { continue; } last_online_attempt = now; let key = runtime.key.lock().unwrap().clone(); let Some(key) = key else { continue; }; match validate_license_online(&key) { Ok(reply) if reply.valid && (reply.lifetime || reply.remaining_seconds > 0) => { apply_valid_license(&key, &reply); } Ok(_) => { runtime.valid.store(false, Ordering::Release); clear_cached_license(); set_active(false); unsafe { if !HWND_MAIN.is_null() { PostMessageW(HWND_MAIN, WM_LICENSE_INVALID, 0, 0); } } } Err(_) => { let too_old = runtime.last_ok.lock().unwrap() .map(|t| now.duration_since(t) >= Duration::from_secs(LICENSE_NETWORK_GRACE_SECS)) .unwrap_or(true); if too_old { runtime.valid.store(false, Ordering::Release); set_active(false); unsafe { if !HWND_MAIN.is_null() { PostMessageW(HWND_MAIN, WM_LICENSE_INVALID, 0, 0); } } } } } } } 